const evaluator = $input.first().json;
const score = evaluator.overall_score || evaluator.seo_geo_evaluator?.overall_score || 0;
const criticalBlockers = evaluator.critical_blockers || evaluator.seo_geo_evaluator?.critical_blockers || [];
const retryCount = $('Initialize Accumulator').item.json.retry_count || 0;
const maxRetries = 2;

if (criticalBlockers.length > 0) {
  return [{ json: { action: 'flag_human_review', score, criticalBlockers } }];
}

if (score >= 70) {
  return [{ json: { action: 'proceed', score } }];
}

if (retryCount < maxRetries) {
  return [{ json: { action: 'retry', score, retry_count: retryCount + 1, retry_prompt: evaluator.retry_prompt || '' } }];
}

return [{ json: { action: 'flag_human_review', score, reason: 'max retries exceeded' } }];

